  grad.addColorStop(1, frac < 0.3 ? '#ff5c7a' : '#ffe082');
  ctx.fillStyle = grad;
  ctx.fillRect(bx, by, bw * frac, 8);
  ctx.fillStyle = 'rgba(125,143,163,0.9)';
  ctx.fillText('LUMEN', bx, by - 6);
  ctx.restore();
}

function drawMenu(ctx, W, H, world) {
